/**
 * Generate `.claude/hooks/generated-artifacts.json`: every artifact of `GENERATORS`
 * (`scripts/generators.ts`, the table `check:drift` runs) mapped to the `gen:*` script that writes
 * it. The local-gate hook is plain Node with zero dependencies and cannot import TypeScript, so it
 * reads this JSON to refuse an Edit/Write of a generated file. Derived, never retyped; drift-gated
 * like every other artifact (it is a row of the table it renders). Run `npm run gen:generated-artifacts`.
 */

import { writeFileSync } from "node:fs";
import { resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { GENERATED_ARTIFACTS_JSON, GENERATORS } from "./generators.js";

const ROOT = resolve(fileURLToPath(new URL(".", import.meta.url)), "..");

/** The JSON text: `{ "comment": …, "artifacts": { "<path>": "<gen:script>" } }`, in table order. */
export function renderGeneratedArtifacts(): string {
  const artifacts: Record<string, string> = {};
  for (const { script, artifacts: paths } of GENERATORS) {
    for (const p of paths) {
      if (artifacts[p] !== undefined) throw new Error(`${p} is written by both ${artifacts[p]} and ${script}`);
      artifacts[p] = script;
    }
  }
  const doc = {
    comment: "GENERATED by scripts/gen-generated-artifacts.ts from scripts/generators.ts. Do not edit by hand.",
    artifacts,
  };
  return `${JSON.stringify(doc, null, 2)}\n`;
}

if (process.argv[1] && fileURLToPath(import.meta.url) === resolve(process.argv[1])) {
  writeFileSync(resolve(ROOT, GENERATED_ARTIFACTS_JSON), renderGeneratedArtifacts());
  console.log(`wrote ${GENERATED_ARTIFACTS_JSON}`);
}
